// 3D model of the face: the muscles of facial expression on both sides, the
// facial nerve branches, facial vessels, parotid and duct, from Z-Anatomy
// meshes (CC BY-SA 4.0, based on BodyParts3D). Geometry and the traced courses
// live in data/face-meshes.js, generated by tools/export_zanatomy.py.
// Coordinates are centimetres: +y = superior, +z = anterior, right side -x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.face = {
  // Default view: three-quarter view of the right face.
  camera: { target: [0, 0.5, 0.5], radius: 30, theta: -0.6, phi: 1.5 },

  // [theta, phi] for the view buttons. "Lateral" shows the right side (-x).
  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [-0.2, 2.4],
    anterior: [0, Math.PI / 2]
  },
  viewLabels: { inferior: "From below", anterior: "Front" },

  // Starting axial level (0 = bottom, 1 = top): through the cheeks and upper lip.
  sectionLevel: 0.42,

  look: {
    skull: { kind: "bone", opacity: 0.55 },
    facial_skeleton: { kind: "bone" },
    mandible: { kind: "bone" },
    nasal_cartilages: { kind: "cartilage", color: 0xc9d6e0 },
    galea: { kind: "cartilage", color: 0xd6d0e4, opacity: 0.45 },
    frontalis: { kind: "muscle", color: 0xb5524a },
    occipitalis: { kind: "muscle", color: 0xb5524a },
    temporoparietalis: { kind: "muscle", color: 0xa94b45, opacity: 0.85 },
    orbicularis_oculi: { kind: "muscle", color: 0xc0605a },
    corrugator: { kind: "muscle", color: 0x9c3a3c },
    procerus: { kind: "muscle", color: 0xa4423f },
    nasalis: { kind: "muscle", color: 0xa4423f },
    depressor_septi: { kind: "muscle", color: 0x9c3a3c },
    orbicularis_oris: { kind: "muscle", color: 0xc0605a },
    levator_labii: { kind: "muscle", color: 0xa94b45 },
    zygomaticus_minor: { kind: "muscle", color: 0xb5524a },
    zygomaticus_major: { kind: "muscle", color: 0xbf5a4f },
    levator_anguli_oris: { kind: "muscle", color: 0x9c3a3c },
    risorius: { kind: "muscle", color: 0xb5524a },
    depressor_anguli_oris: { kind: "muscle", color: 0xa94b45 },
    depressor_labii: { kind: "muscle", color: 0x9c3a3c },
    mentalis: { kind: "muscle", color: 0xb5524a },
    platysma: { kind: "muscle", color: 0xa4423f, opacity: 0.75 },
    masseter: { kind: "muscle", color: 0x8f3739 },
    temporalis: { kind: "muscle", color: 0x8f3739, opacity: 0.8 },
    parotid: { kind: "gland", color: 0xd9a46e },
    parotid_duct: { kind: "duct", color: 0xf4e3a6 },
    facial_trunk: { kind: "nerve" },
    temporal_branch: { kind: "nerve" },
    zygomatic_branch: { kind: "nerve" },
    buccal_branch: { kind: "nerve" },
    mmn: { kind: "nerve" },
    cervical_branch: { kind: "nerve" },
    posterior_auricular_nerve: { kind: "nerve" },
    mental_nerve: { kind: "nerve", color: 0xd9b84a },
    facial_artery: { kind: "artery" },
    labial_arteries: { kind: "artery" },
    transverse_facial: { kind: "artery" },
    supraorbital_arteries: { kind: "artery" },
    facial_vein: { kind: "vein" }
  },

  build(THREE, h) {
    return h.fromMeshes("face", this.look);
  }
};
